/* Immediate dominators of a reachable CFG rooted at 0, iterative bit sets. */
#include <stdio.h>
#include <stdint.h>
int main(void){int n,m,g[32][32]={0},reach[32]={0},queue[32],h=0,t=0;uint64_t dom[32];if(scanf("%d%d",&n,&m)!=2||n<1||n>32||m<0||m>1024)return 1;for(int i=0;i<m;i++){int u,v;if(scanf("%d%d",&u,&v)!=2||u<0||u>=n||v<0||v>=n)return 1;g[u][v]=1;}reach[0]=1;queue[t++]=0;while(h<t){int u=queue[h++];for(int v=0;v<n;v++)if(g[u][v]&&!reach[v])reach[v]=1,queue[t++]=v;}uint64_t all=(1ULL<<n)-1;for(int i=0;i<n;i++)dom[i]=i?all:1;int changed=1;while(changed){changed=0;for(int v=1;v<n;v++)if(reach[v]){uint64_t d=all;for(int u=0;u<n;u++)if(reach[u]&&g[u][v])d&=dom[u];d|=1ULL<<v;if(d!=dom[v])dom[v]=d,changed=1;}}for(int v=1;v<n;v++){if(!reach[v]){printf("%d: unreachable\n",v);continue;}int id=-1;for(int u=0;u<n;u++)if(u!=v&&(dom[v]&(1ULL<<u))){int nearest=1;for(int w=0;w<n;w++)if(w!=v&&w!=u&&(dom[v]&(1ULL<<w))&&(dom[w]&(1ULL<<u)))nearest=0;if(nearest)id=u;}printf("idom(%d)=%d\n",v,id);}return 0;}